25	// disconnectedOnce ensures the disconnection warning runs at most once per process.
26	var disconnectedOnce sync.Once //nolint:gochecknoglobals // intentional per-process gate
27	
28	// IsMetadataDisconnected checks whether the local primary metadata ref and
29	// the provided fetched or remote-tracking ref exist but share no common
30	// ancestor.
31	func IsMetadataDisconnected(ctx context.Context, repo *git.Repository, remoteRefName plumbing.ReferenceName) (bool, error) {
32		refs := checkpoint.ResolveRefs(ctx)
33		localRef, err := repo.Reference(refs.Primary, true)
34		if errors.Is(err, plumbing.ErrReferenceNotFound) {
35			return false, nil
36		}
37		if err != nil {
38			return false, fmt.Errorf("failed to check local primary metadata ref: %w", err)
39		}
40	
41		remoteRef, err := repo.Reference(remoteRefName, true)
42		if errors.Is(err, plumbing.ErrReferenceNotFound) {
43			return false, nil
44		}
45		if err != nil {
46			return false, fmt.Errorf("failed to check remote metadata ref: %w", err)
47		}
48	
49		if localRef.Hash() == remoteRef.Hash() {
50			return false, nil
51		}
52	
53		repoPath, err := getRepoPath(repo)
54		if err != nil {
55			return false, err
56		}
57	
58		return isDisconnected(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
59	}
60	
61	// FirstReadCandidateTrackingRef returns the remote name and remote-tracking
62	// ref of the first checkpoint read candidate (elected sync remote first, then
63	// the legacy origin tier) whose tracking ref for primary exists locally.
64	// Pure read; ok is false when no candidate has a tracking ref (or the chain
65	// is empty).
66	func FirstReadCandidateTrackingRef(ctx context.Context, repo *git.Repository, primary plumbing.ReferenceName) (string, plumbing.ReferenceName, bool) {
67		for _, remoteName := range CheckpointReadRemotes(ctx) {
68			refName := plumbing.NewRemoteReferenceName(remoteName, primary.Short())
69			if _, err := repo.Reference(refName, true); err == nil {
70				return remoteName, refName, true
71			}
72		}
73		return "", "", false
74	}
75	
76	// WarnIfMetadataDisconnected checks (once per process) whether the metadata
77	// branch is disconnected and prints a warning to stderr if so. The check runs
78	// against the first checkpoint read candidate whose remote-tracking ref
79	// exists (pure read across both tiers).
80	// It does NOT fix the problem — users are directed to 'entire doctor'.
81	//
82	// Uses sync.Once, so a transient failure on the first call permanently suppresses
83	// the warning. This is acceptable because the check is advisory only and
84	// 'entire doctor' is the authoritative repair path.
85	func WarnIfMetadataDisconnected() {
86		disconnectedOnce.Do(func() {
87			ctx := context.Background()
88			repo, err := OpenRepository(ctx)
89			if err != nil {
90				logging.Debug(ctx, "metadata disconnection check: could not open repository",
91					slog.String("error", err.Error()))
92				return
93			}
94			defer repo.Close()
95			refs := checkpoint.ResolveRefs(ctx)
96			if !refs.PrimaryFetchableFromRemote() {
97				return // no remote tracks Primary; nothing to disconnect from
98			}
99			_, remoteRefName, ok := FirstReadCandidateTrackingRef(ctx, repo, refs.Primary)
100			if !ok {
101				return // no candidate has a tracking ref; nothing to disconnect from
102			}
103			disconnected, err := IsMetadataDisconnected(ctx, repo, remoteRefName)
104			if err != nil {
105				logging.Debug(ctx, "metadata disconnection check failed",
106					slog.String("error", err.Error()))
107				return
108			}
109			if !disconnected {
110				return
111			}
112			fmt.Fprintln(os.Stderr, "[entire] Warning: Local and remote session metadata branches are disconnected.")
113			fmt.Fprintln(os.Stderr, "[entire] Some checkpoints from remote may not be visible. Run 'entire doctor' to fix.")
114		})
115	}
116	
117	// ReconcileDisconnectedMetadataRef detects and repairs disconnected local/remote
118	// metadata refs. Disconnected means no common ancestor, which
119	// only happens due to the empty-orphan bug. Diverged (shared ancestor) is normal
120	// and handled by the push path.
121	//
122	// Repair strategy: cherry-pick local commits onto remote tip, preserving all data.
123	// Checkpoint shards use unique paths (<id[:2]>/<id[2:]>/), so cherry-picks always
124	// apply cleanly.
125	//
126	// Progress messages are written to w (typically os.Stderr for hooks or
127	// cmd.ErrOrStderr() for commands).
128	// The remote ref can be either a remote-tracking ref or a temporary fetched ref.
129	func ReconcileDisconnectedMetadataRef(
130		ctx context.Context,
131		repo *git.Repository,
132		localRefName plumbing.ReferenceName,
133		remoteRefName plumbing.ReferenceName,
134		w io.Writer,
135	) error {
136		advance := func(hash plumbing.Hash) error {
137			return setRefHash(repo, localRefName, hash)
138		}
139	
140		// Check local ref
141		localRef, err := repo.Reference(localRefName, true)
142		if errors.Is(err, plumbing.ErrReferenceNotFound) {
143			return nil // No local ref — nothing to reconcile
144		}
145		if err != nil {
146			return fmt.Errorf("failed to check local metadata ref: %w", err)
147		}
148	
149		// Check remote-tracking or fetched ref
150		remoteRef, err := repo.Reference(remoteRefName, true)
151		if errors.Is(err, plumbing.ErrReferenceNotFound) {
152			return nil // No remote ref — nothing to reconcile
153		}
154		if err != nil {
155			return fmt.Errorf("failed to check remote metadata ref: %w", err)
156		}
157	
158		localHash := localRef.Hash()
159		remoteHash := remoteRef.Hash()
160	
161		// Same hash — nothing to do
162		if localHash == remoteHash {
163			return nil
164		}
165	
166		// Check if disconnected using git merge-base
167		repoPath, err := getRepoPath(repo)
168		if err != nil {
169			return err
170		}
171	
172		disconnected, err := isDisconnected(ctx, repoPath, localHash.String(), remoteHash.String())
173		if err != nil {
174			return fmt.Errorf("failed to check metadata ref ancestry: %w", err)
175		}
176		if !disconnected {
177			// Shared ancestry (diverged or ancestor) — not our problem
178			return nil
179		}
180	
181		// Disconnected — cherry-pick local commits onto remote tip
182		fmt.Fprintln(w, "[entire] Detected disconnected session metadata (local and remote share no common ancestor)")
183	
184		shallow, err := loadShallowHashes(ctx, repoPath)
185		if err != nil {
186			return fmt.Errorf("failed to load shallow boundaries: %w", err)
187		}
188	
189		// Collect local commits oldest-first
190		localCommits, err := collectCommitChain(repo, localHash, shallow)
191		if err != nil {
192			return fmt.Errorf("failed to collect local commits: %w", err)
193		}
194	
195		// Filter out empty-tree commits (the orphan bug commit)
196		var dataCommits []*object.Commit
197		for _, c := range localCommits {
198			tree, treeErr := c.Tree()
199			if treeErr != nil {
200				return fmt.Errorf("failed to read tree for commit %s: %w", c.Hash.String()[:7], treeErr)
201			}
202			if len(tree.Entries) > 0 {
203				dataCommits = append(dataCommits, c)
204			}
205		}
206	
207		if len(dataCommits) == 0 {
208			// Local only had empty orphan — just point to remote
209			if err := advance(remoteHash); err != nil {
210				return fmt.Errorf("failed to reset metadata ref to remote: %w", err)
211			}
212			fmt.Fprintln(w, "[entire] Done — local had no checkpoint data, reset to remote")
213			return nil
214		}
215	
216		fmt.Fprintf(w, "[entire] Cherry-picking %d local checkpoint(s) onto remote...\n", len(dataCommits))
217	
218		newTip, err := cherryPickOnto(ctx, repo, remoteHash, dataCommits, shallow)
219		if err != nil {
220			return fmt.Errorf("failed to cherry-pick local commits onto remote: %w", err)
221		}
222	
223		if err := advance(newTip); err != nil {
224			return fmt.Errorf("failed to update metadata ref: %w", err)
225		}
226	
227		fmt.Fprintln(w, "[entire] Done — all local and remote checkpoints preserved")
228		return nil
229	}
230	
231	// isDisconnected checks if two commits have no common ancestor using git merge-base.
232	// Returns (true, nil) if disconnected, (false, nil) if they share ancestry,
233	// or (false, error) if git merge-base failed for another reason.
234	//
235	// git merge-base exit codes:
236	//   - 0: common ancestor found (shared ancestry)
237	//   - 1: no common ancestor (disconnected)
238	//   - 128+: error (corrupt repo, invalid hash, etc.)
239	func isDisconnected(ctx context.Context, repoPath, hashA, hashB string) (bool, error) {
240		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
241		defer cancel()
242		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
243		cmd.Dir = repoPath
244		if err := cmd.Run(); err != nil {
245			var exitErr *exec.ExitError
246			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
247				return true, nil // No common ancestor — disconnected
248			}
249			return false, fmt.Errorf("git merge-base failed: %w", err)
250		}
251		return false, nil // Shared ancestry
252	}
253	
254	// collectCommitChain walks from tip to root following first parent, returns oldest-first.
255	// Commits listed in shallow are treated as roots — the walk stops at them without
256	// traversing into their parents. go-git's repo.CommitObject().ParentHashes does not
257	// consult .git/shallow on its own, so without this check the walk would stroll past
258	// shallow boundaries into stale objects left in the pack (e.g., when the remote
259	// branch has been rebuilt since the last full fetch), producing a phantom chain of
260	// commits that no longer represent the actual checkpoint history.
261	func collectCommitChain(repo *git.Repository, tip plumbing.Hash, shallow map[plumbing.Hash]bool) ([]*object.Commit, error) {
262		var chain []*object.Commit
263		current := tip
264	
265		reachedRoot := false
266		for range MaxCommitTraversalDepth {
267			commit, err := repo.CommitObject(current)
268			if err != nil {
269				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
270			}
271			chain = append(chain, commit)
272	
273			if len(commit.ParentHashes) == 0 {
274				reachedRoot = true
275				break
276			}
277			if shallow[current] {
278				// Shallow boundary — treat as a root.
279				reachedRoot = true
280				break
281			}
282			current = commit.ParentHashes[0]
283		}
284	
285		if !reachedRoot {
286			return nil, fmt.Errorf("commit chain exceeded %d commits without reaching root; aborting reconciliation", MaxCommitTraversalDepth)
287		}
288	
289		// Reverse to oldest-first
290		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
291			chain[i], chain[j] = chain[j], chain[i]
292		}
293	
294		return chain, nil
295	}
296	
297	// loadShallowHashes returns the commit hashes listed in the repository's
298	// shallow file, or an empty map if the repository is not shallow.
299	func loadShallowHashes(ctx context.Context, repoPath string) (map[plumbing.Hash]bool, error) {
300		cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
301		cmd.Dir = repoPath
302		out, err := cmd.Output()
303		if err != nil {
304			return nil, fmt.Errorf("git rev-parse --git-common-dir: %w", err)
305		}
306		gitDir := strings.TrimSpace(string(out))
307		if !filepath.IsAbs(gitDir) {
308			gitDir = filepath.Join(repoPath, gitDir)
309		}
310		// Path is constructed from git's own --git-common-dir output, not user input.
311		data, err := os.ReadFile(filepath.Join(gitDir, "shallow")) //nolint:gosec // see comment above
312		if err != nil {
313			if errors.Is(err, os.ErrNotExist) {
314				return map[plumbing.Hash]bool{}, nil
315			}
316			return nil, fmt.Errorf("read shallow file: %w", err)
317		}
318		set := map[plumbing.Hash]bool{}
319		for _, line := range strings.Split(string(data), "\n") {
320			line = strings.TrimSpace(line)
321			if line == "" {
322				continue
323			}
324			set[plumbing.NewHash(line)] = true
325		}
326		return set, nil
327	}
328	
329	// cherryPickOnto applies each commit's delta onto base, building a linear chain.
330	// For each commit, it computes the full diff from its parent (additions, modifications,
331	// and deletions), then applies that delta onto the current tip's tree.
332	//
333	// Commits listed in shallow are treated as roots: their delta is computed against
334	// an empty tree rather than against their (past-the-boundary) parent. Without this,
335	// a shallow-boundary commit would be diffed against a stale parent tree whose
336	// objects live in the local pack but no longer represent the actual checkpoint
337	// history — producing nonsense changes when replayed onto the remote tip.
338	func cherryPickOnto(ctx context.Context, repo *git.Repository, base plumbing.Hash, commits []*object.Commit, shallow map[plumbing.Hash]bool) (plumbing.Hash, error) {
339		currentTip := base
340	
341		for _, commit := range commits {
342			changes, err := treeChangesForCherryPick(ctx, repo, commit, shallow)
343			if err != nil {
344				return plumbing.ZeroHash, err
345			}
346			if len(changes) == 0 {
347				continue // Skip no-op commits
348			}
349	
350			tipCommit, err := repo.CommitObject(currentTip)
351			if err != nil {
352				return plumbing.ZeroHash, fmt.Errorf("failed to get tip commit: %w", err)
353			}
354	
355			mergedTreeHash, err := checkpoint.ApplyTreeChanges(ctx, repo, tipCommit.TreeHash, changes)
356			if err != nil {
357				return plumbing.ZeroHash, fmt.Errorf("failed to apply cherry-pick changes: %w", err)
358			}
359	
360			// Create new commit on top of current tip, preserving original message/author
361			newHash, err := createCherryPickCommit(ctx, repo, mergedTreeHash, currentTip, commit)
362			if err != nil {
363				return plumbing.ZeroHash, fmt.Errorf("failed to create cherry-pick commit: %w", err)
364			}
365	
366			currentTip = newHash
367		}
368	
369		return currentTip, nil
370	}
371	
372	func treeChangesForCherryPick(ctx context.Context, repo *git.Repository, commit *object.Commit, shallow map[plumbing.Hash]bool) ([]checkpoint.TreeChange, error) {
373		commitTree, err := commit.Tree()
374		if err != nil {
375			return nil, fmt.Errorf("failed to get tree for commit %s: %w", commit.Hash, err)
376		}
377	
378		var parentTree *object.Tree
379		// Shallow-boundary commits are treated as roots — see cherryPickOnto for why.
380		if len(commit.ParentHashes) > 0 && !shallow[commit.Hash] {
381			parentCommit, pErr := repo.CommitObject(commit.ParentHashes[0])
382			if pErr != nil {
383				return nil, fmt.Errorf("failed to get parent commit %s: %w", commit.ParentHashes[0], pErr)
384			}
385			parentTree, err = parentCommit.Tree()
386			if err != nil {
387				return nil, fmt.Errorf("failed to get parent tree for commit %s: %w", commit.ParentHashes[0], err)
388			}
389		}
390	
391		changes, err := object.DiffTreeContext(ctx, parentTree, commitTree)
392		if err != nil {
393			return nil, fmt.Errorf("failed to diff commit %s against parent: %w", commit.Hash, err)
394		}
395	
396		treeChanges := make([]checkpoint.TreeChange, 0, len(changes))
397		for _, change := range changes {
398			treeChange, changeErr := changeToTreeChange(change)
399			if changeErr != nil {
400				return nil, fmt.Errorf("failed to convert change in commit %s: %w", commit.Hash, changeErr)
401			}
402			treeChanges = append(treeChanges, treeChange)
403		}
404		return treeChanges, nil
405	}
406	
407	func changeToTreeChange(change *object.Change) (checkpoint.TreeChange, error) {
408		action, err := change.Action()
409		if err != nil {
410			return checkpoint.TreeChange{}, fmt.Errorf("change action: %w", err)
411		}
412	
413		switch action {
414		case merkletrie.Insert, merkletrie.Modify:
415			entry := change.To.TreeEntry
416			return checkpoint.TreeChange{
417				Path: change.To.Name,
418				Entry: &object.TreeEntry{
419					Name: entry.Name,
420					Mode: entry.Mode,
421					Hash: entry.Hash,
422				},
423			}, nil
424		case merkletrie.Delete:
425			return checkpoint.TreeChange{Path: change.From.Name}, nil
426		default:
427			return checkpoint.TreeChange{}, fmt.Errorf("unsupported action %s", action)
428		}
429	}
430	
431	// createCherryPickCommit creates a new commit on top of parent, preserving the
432	// original commit's message and author.
433	func createCherryPickCommit(ctx context.Context, repo *git.Repository, treeHash, parent plumbing.Hash, original *object.Commit) (plumbing.Hash, error) {
434		committerName, committerEmail := GetGitAuthorFromRepo(repo)
435		now := time.Now()
436	
437		commit := &object.Commit{
438			TreeHash:     treeHash,
439			ParentHashes: []plumbing.Hash{parent},
440			Author:       original.Author,
441			Committer: object.Signature{
442				Name:  committerName,
443				Email: committerEmail,
444				When:  now,
445			},
446			Message: original.Message,
447		}
448	
449		checkpoint.SignCommitBestEffort(ctx, commit)
450	
451		obj := repo.Storer.NewEncodedObject()
452		if err := commit.Encode(obj); err != nil {
453			return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
454		}
455	
456		hash, err := repo.Storer.SetEncodedObject(obj)
457		if err != nil {
458			return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
459		}
460	
461		return hash, nil
462	}
463	
464	// getRepoPath returns the filesystem path for the repository's worktree.
465	func getRepoPath(repo *git.Repository) (string, error) {
466		wt, err := repo.Worktree()
467		if err != nil {
468			return "", fmt.Errorf("failed to get worktree: %w", err)
469		}
470		return wt.Filesystem().Root(), nil
471	}
